/**
 * The subset of a profile a {@link PlayerCard} needs.
 *
 * Both `PlayerProfile` (mine) and `PublicPlayerProfile` (someone else's) satisfy it,
 * which is what lets one component serve the profile page, the match board, search
 * results and scorecards.
 */
export type PlayerCardProfile = {
  id: string;
  name: string;
  photo_url: string;
  area?: string;
  bio?: string;
  reliability_score: number;
  attributes: readonly PlayerAttributeValue[];
  sport_cards: readonly PlayerSportCard[];
};
